<?php
declare(strict_types=1);
require_once __DIR__.'/documents.php';require_once dirname(__DIR__).'/billing/notifications.php';
function lc_finance_gate():void{if(crm_query("SELECT state FROM nd_schema_migrations WHERE version='015_lifecycle_payments'")->fetchColumn()!=='applied')crm_fail(503,'Ручной учёт платежей ещё не подготовлен.');}
function lc_invoice(array $a,int $id,bool $lock=false):array{$i=bill_invoice($a,$id,$lock);$s=crm_query('SELECT s.*,d.project_id FROM nd_lc_schedule_entries s JOIN nd_lc_document_bindings b ON b.id=s.binding_id JOIN nd_cc_revisions r ON r.id=b.revision_id JOIN nd_cc_documents d ON d.id=r.document_id WHERE s.invoice_id=?',[$id])->fetch();if(!$s)crm_fail(404,'Запрос оплаты не найден.');cc_project($a,(int)$s['project_id']);$i['schedule']=$s;return $i;}
function lc_schedule_activate(array $a,int $binding,array $d):array{
 cc_owner($a);$b=lc_binding($a,$binding,true);cc_revision($a,(int)$b['revision_id']);$order=crm_record('orders',(int)$b['order_id'],true);if($b['state']!=='AGREED'||$b['kind']!=='agreement'||($d['confirm']??false)!==true)crm_fail(409,'Нужен проверенный подписанный договор и явное подтверждение.');
 $invoiceTemplate=lc_template(cc_id($d['invoice_template_id']??null),true);if($invoiceTemplate['kind']!=='invoice'||$invoiceTemplate['state']!=='APPROVED')crm_fail(409,'Нужен отдельный одобренный шаблон запроса оплаты (не чека).');
 $existing=crm_query('SELECT * FROM nd_lc_schedule_entries WHERE order_id=? ORDER BY position FOR UPDATE',[$b['order_id']])->fetchAll();if($existing){if((int)$existing[0]['binding_id']!==$binding)crm_fail(409,'График уже закреплён другим договором. Изменение требует отдельного соглашения.');return ['ok'=>true,'id'=>(int)$existing[0]['id'],'items'=>$existing];}
 if(crm_query("SELECT id FROM nd_invoices WHERE order_id=? AND state='issued' LIMIT 1",[$order['id']])->fetchColumn())crm_fail(409,'У заказа уже есть счета: сначала требуется сверка, повторное начисление запрещено.');
 $input=json_decode($b['input_snapshot'],true,512,JSON_THROW_ON_ERROR);$schedule=$input['payment_schedule']??null;if(!is_array($schedule)||!count($schedule)&&bill_minor($order['total_amount'])!==0)crm_fail(409,'В подписанном снимке нет структурированного графика. Подготовьте новую версию договора.');$sum=array_sum(array_column($schedule,'amount_minor'));if($sum!==bill_minor($order['total_amount']))crm_fail(409,'Цена заказа отличается от подписанного графика.');
 lc_issue_schedule_entries($a,$order,$b,$input,$schedule,$invoiceTemplate);
 lc_audit($a,'order',(int)$order['id'],count($schedule)?'schedule_activated':'zero_price_schedule_confirmed',null,['binding_id'=>$binding,'hash'=>$b['generated_hash']]);return ['ok'=>true,'id'=>(int)$order['id']];
}
function lc_issue_schedule_entries(array $a,array $order,array $b,array $input,array $schedule,array $invoiceTemplate,int $offset=0,int $priorNet=0):array{
 $binding=(int)$b['id'];$ids=[];
 foreach($schedule as $n=>$row){$planned=(int)$row['amount_minor'];$covered=min($priorNet,$planned);$priorNet-=$covered;$dueAmount=$planned-$covered;$position=$offset+$n+1;$invoiceFields=$input['fields'];$invoiceFields['price']=bill_decimal($dueAmount);$invoiceFields['payment_schedule']=$row['label'].', до '.$row['due_on'];$rendered=[];foreach($invoiceTemplate['clauses'] as $key=>$text)$rendered[$key]=preg_replace_callback('/\{\{([^{}]+)\}\}/',fn($m)=>$invoiceFields[$m[1]],$text);$number='ND-'.$order['id'].'-P'.$position;$snapshot=['number'=>$number,'issued_at'=>gmdate('Y-m-d H:i:s'),'due_on'=>$row['due_on'],'merchant'=>['legal_name'=>$input['fields']['owner_name'],'registration'=>'НПД, ИНН '.$input['fields']['owner_inn'],'address'=>$input['fields']['owner_address'],'tax_treatment'=>'Чек формируется исполнителем в Мой налог отдельно','payment_instructions'=>$input['fields']['bank_details']],'customer'=>['name'=>$input['fields']['client_name']],'order'=>['id'=>(int)$order['id'],'number'=>$order['number']],'lines'=>[['description'=>$row['label'],'quantity_milli'=>1000,'unit_minor'=>$row['amount_minor'],'total_minor'=>$row['amount_minor']]],'total_minor'=>$dueAmount,'agreed_installment_minor'=>$planned,'covered_by_prior_verified_payments_minor'=>$covered,'currency'=>'RUB','agreement_hash'=>$b['generated_hash'],'template'=>['id'=>(int)$invoiceTemplate['id'],'checksum'=>$invoiceTemplate['checksum'],'revision_number'=>(int)$invoiceTemplate['revision_number'],'clauses'=>$invoiceTemplate['clauses']],'rendered'=>$rendered];
 crm_query("INSERT INTO nd_invoices(customer_id,order_id,number,state,currency,total_minor,due_on,snapshot,snapshot_hash,sent_at,issued_at) VALUES (?,?,?,'issued','RUB',?,?,?,?,UTC_TIMESTAMP(),UTC_TIMESTAMP())",[$order['customer_id'],$order['id'],$number,$dueAmount,$row['due_on'],lc_json($snapshot),hash('sha256',lc_json($snapshot))]);$iid=(int)db()->lastInsertId();$ids[]=$iid;crm_query('INSERT INTO nd_invoice_lines(invoice_id,position,description,quantity_milli,unit_minor,total_minor) VALUES (?,0,?,1000,?,?)',[$iid,$row['label'],$dueAmount,$dueAmount]);
 crm_query('INSERT INTO nd_lc_schedule_entries(order_id,binding_id,position,label,amount_minor,due_on,gate,stage_id,invoice_id) VALUES (?,?,?,?,?,?,?,?,?)',[$order['id'],$binding,$position,$row['label'],$row['amount_minor'],$row['due_on'],$row['gate'],$row['stage_id'],$iid]);bill_emit('lc-invoice:'.$iid,'invoice_issued','invoices',$iid,(int)$order['customer_id']);}
 return $ids;
}
function lc_payment_claim(array $a,int $invoice,array $d):array{
 if($a['type']!=='customer')crm_fail(403,'Сообщение об оплате отправляет клиент.');$i=lc_invoice($a,$invoice,true);if($i['state']!=='issued')crm_fail(409,'Запрос оплаты не действует.');$amount=bill_minor($d['amount']??null);if($amount<1)crm_fail(422,'Укажите фактически переведённую сумму.');$date=lc_paid_at($d);$payer=cc_text($d,'payer',190);$reference=cc_text($d,'reference',190);$file=$d['file_id']??null;if($file!==null){$files=cc_files_for($a,(int)$i['schedule']['project_id'],[cc_id($file)],true);cc_file_path($files[0]);}
 // Identical claims with a new request key are still the same report, never new income.
 $old=crm_query('SELECT id FROM nd_lc_payment_claims WHERE invoice_id=? AND account_id=? AND amount_minor=? AND paid_at=? AND reference=? LIMIT 1',[$invoice,$a['id'],$amount,$date,$reference])->fetchColumn();if($old)return ['ok'=>true,'id'=>(int)$old];
 crm_query('INSERT INTO nd_lc_payment_claims(invoice_id,account_id,amount_minor,paid_at,payer,reference,file_id) VALUES (?,?,?,?,?,?,?)',[$invoice,$a['id'],$amount,$date,$payer,$reference,$file]);$id=(int)db()->lastInsertId();lc_audit($a,'claim',$id,'reported',null,['invoice_id'=>$invoice,'amount_minor'=>$amount]);crm_notice('lc-claim:'.$id,'orders',(int)$i['order_id'],'Клиент сообщил об оплате. Требуется проверка поступления по банку.');return ['ok'=>true,'id'=>$id,'payment_verified'=>false];
}
function lc_verify_bank(array $a,int $invoice,array $d):array{
 cc_owner($a);$i=lc_invoice($a,$invoice,true);if($i['state']!=='issued'||($d['confirm_actual_bank']??false)!==true)crm_fail(422,'Подтвердите проверку реальных банковских данных; сообщение клиента не подтверждает поступление.');$amount=bill_minor($d['amount']??null);if($amount<1)crm_fail(422,'Сумма поступления должна быть положительной.');$date=lc_paid_at($d);$method=$d['method']??'';$due=lc_receipt_due($date,$method);$payer=cc_text($d,'payer',190);$reference=cc_text($d,'reference',190);$reason=cc_text($d,'reason',2000);$entry=cc_text($d,'bank_entry_id',190);$binding=lc_binding($a,(int)$i['schedule']['binding_id']);$input=json_decode($binding['input_snapshot'],true,512,JSON_THROW_ON_ERROR);$bankKey=hash('sha256',$input['fields']['bank_account']."\0".$entry);
 if(crm_query('SELECT id FROM nd_lc_bank_records WHERE bank_entry_hash=?',[$bankKey])->fetchColumn())crm_fail(409,'Эта банковская операция уже учтена. Проверьте существующую запись, не создавайте повторный доход.');
 $file=$d['file_id']??null;if($file!==null){$f=cc_file($a,cc_id($file));if((int)$f['project_id']!==(int)$i['schedule']['project_id']||$f['archived_at']!==null)crm_fail(422,'Подтверждение относится к другому проекту.');cc_file_path($f);}
 $claim=null;if(($d['claim_id']??null)!==null){$claim=crm_query('SELECT * FROM nd_lc_payment_claims WHERE id=? FOR UPDATE',[cc_id($d['claim_id'])])->fetch();if(!$claim||(int)$claim['invoice_id']!==$invoice||$claim['state']!=='REPORTED')crm_fail(409,'Сообщение уже рассмотрено или относится к другому счёту.');if(((int)$claim['amount_minor']!==$amount||$claim['payer']!==$payer)&&($d['reconciliation_confirmed']??false)!==true)crm_fail(409,'Сумма/плательщик отличаются от сообщения клиента. Явно подтвердите сверку и объясните основание.');}
 $provider='manual-bank:'.substr($bankKey,0,64);crm_query("INSERT INTO nd_payment_attempts(invoice_id,request_key,provider,merchant_hash,provider_id,amount_minor,currency,state,verified_at) VALUES (?,?,'manual_bank',?,?,?,'RUB','succeeded',UTC_TIMESTAMP())",[$invoice,$d['request_key'],hash('sha256',$input['fields']['bank_account']),$provider,$amount]);$attempt=(int)db()->lastInsertId();crm_query("INSERT INTO nd_payment_transactions(attempt_id,provider_id,amount_minor,currency,settled_at) VALUES (?,?,?,'RUB',?)",[$attempt,$provider,$amount,$date]);$tx=(int)db()->lastInsertId();
 crm_query('INSERT INTO nd_lc_bank_records(transaction_id,bank_entry_hash,bank_reference,payer,paid_at,method,evidence_file_id,reason,verified_by) VALUES (?,?,?,?,?,?,?,?,1)',[$tx,$bankKey,$reference,$payer,$date,$method,$file,$reason]);
 $buyer=$input['fields']['client_type'];$inn=$input['fields']['client_inn']??null;if($buyer!=='person'&&!lc_inn_valid((string)$inn))crm_fail(422,'Для чека ИП/организации нужны корректные реквизиты покупателя.');$service=cc_text($d,'service_description',500);
 crm_query("INSERT INTO nd_lc_receipt_tasks(transaction_id,order_id,amount_minor,paid_at,method,buyer_type,buyer_inn,service_description,due_at,rule_version) VALUES (?,?,?,?,?,?,?,?,?,'fns_422_art14_2026_10_27')",[$tx,$i['order_id'],$amount,$date,$method,$buyer,$inn?:null,$service,$due]);$receipt=(int)db()->lastInsertId();if($claim)crm_query("UPDATE nd_lc_payment_claims SET state='RECONCILED',matched_attempt_id=?,reason=?,version=version+1 WHERE id=?",[$attempt,$reason,$claim['id']]);
 lc_audit($a,'payment',$tx,'bank_verified_owner_attested',null,['invoice_id'=>$invoice,'amount_minor'=>$amount,'bank_entry_hash'=>$bankKey,'claim_id'=>$claim['id']??null,'reason'=>$reason]);bill_emit('lc-payment:'.$tx,'payment_confirmed','invoices',$invoice,(int)$i['customer_id']);crm_notice('lc-receipt:'.$receipt,'orders',(int)$i['order_id'],'Нужен официальный чек Мой налог на подтверждённое поступление.');return ['ok'=>true,'id'=>$tx,'attempt_id'=>$attempt,'receipt_task_id'=>$receipt,'evidence_source'=>'OWNER_ATTESTED','independently_verified'=>false];
}
function lc_receipt(array $a,int $id,bool $lock=false):array{$r=crm_query('SELECT * FROM nd_lc_receipt_tasks WHERE id=?'.($lock?' FOR UPDATE':''),[$id])->fetch();if(!$r)crm_fail(404,'Задача чека не найдена.');$order=crm_record('orders',(int)$r['order_id']);if($a['type']==='customer'&&(int)$order['customer_id']!==$a['customer_id'])crm_fail(404,'Задача чека не найдена.');return $r;}
function lc_receipt_record(array $a,int $id,string $action,array $d):array{
 cc_owner($a);$r=lc_receipt($a,$id,true);crm_version($d,$r);if(($d['confirm_issued_in_mytax']??false)!==true&&$action!=='transmit')crm_fail(422,'Сначала оформите реальный чек или исправление в Мой налог. Локальный документ не является чеком.');$reason=cc_text($d,'reason',2000);$url='';$file=null;$reference='';$issued=null;$transmitted=null;$channel=null;
 if(in_array($action,['issue','correct'],true)){if($action==='issue'&&$r['state']!=='MISSING'||$action==='correct'&&$r['state']!=='CORRECTION_NEEDED')crm_fail(409,'Проверьте состояние задачи чека.');$url=cc_text($d,'official_url',2000,false);if($url!==''&&(filter_var($url,FILTER_VALIDATE_URL)===false||parse_url($url,PHP_URL_SCHEME)!=='https'||parse_url($url,PHP_URL_HOST)!=='lknpd.nalog.ru'||parse_url($url,PHP_URL_USER)!==null||parse_url($url,PHP_URL_PASS)!==null))crm_fail(422,'Используйте официальную HTTPS-ссылку lknpd.nalog.ru без учётных данных.');$reference=cc_text($d,'external_reference',190);$issued=lc_paid_at(['paid_at'=>$d['issued_at']??'']);$file=$d['file_id']??null;if($file!==null){$f=cc_file($a,cc_id($file));$project=crm_query('SELECT id FROM nd_projects WHERE order_id=? AND id=?',[$r['order_id'],$f['project_id']])->fetchColumn();if(!$project||$f['visibility']!=='customer'||$f['archived_at']!==null)crm_fail(422,'Чек должен быть в файлах этого заказа с доступом клиента.');cc_file_path($f);}if($url===''&&$file===null)crm_fail(422,'Приложите официальный чек или его ссылку и подтвердите реальное оформление.');$event=$action==='issue'?'ISSUANCE_RECORDED':'CORRECTION_RECORDED';$state='OWNER_RECORDED';}
 elseif($action==='transmit'){if(!in_array($r['state'],['OWNER_RECORDED','TRANSMISSION_RECORDED'],true)||($d['confirm_transmitted']??false)!==true)crm_fail(422,'Укажите способ и время реальной передачи чека клиенту.');$transmitted=lc_paid_at(['paid_at'=>$d['transmitted_at']??'']);$channel=$d['transmission_channel']??'';if(!in_array($channel,['max','telegram','email','paper','portal'],true))crm_fail(422,'Выберите фактический способ передачи чека.');$event='TRANSMISSION_RECORDED';$state='TRANSMISSION_RECORDED';}else crm_fail(404,'Действие не найдено.');
 crm_query('INSERT INTO nd_lc_receipt_evidence(task_id,action,official_url,file_id,external_reference,issued_at,transmitted_at,transmission_channel,reason,recorded_by) VALUES (?,?,?,?,?,?,?,?,?,1)',[$id,$event,$url?:null,$file,$reference?:null,$issued,$transmitted,$channel,$reason]);$evidence=(int)db()->lastInsertId();crm_query('UPDATE nd_lc_receipt_tasks SET state=?,version=version+1 WHERE id=?',[$state,$id]);lc_audit($a,'receipt',$id,$event,(int)$r['version'],['evidence_id'=>$evidence,'reason'=>$reason,'independently_verified'=>false]);$order=crm_record('orders',(int)$r['order_id']);bill_emit('lc-receipt-evidence:'.$evidence,'new_deliverable','orders',(int)$r['order_id'],(int)$order['customer_id']);return ['ok'=>true,'id'=>$id,'evidence_source'=>'OWNER_ATTESTED','independently_verified'=>false];
}
function lc_refund_record(array $a,int $attempt,array $d):array{
 cc_owner($a);$p=crm_query("SELECT * FROM nd_payment_attempts WHERE id=? AND provider='manual_bank'",[$attempt])->fetch();if(!$p)crm_fail(404,'Поступление не найдено.');$i=lc_invoice($a,(int)$p['invoice_id'],true);$p=crm_query('SELECT * FROM nd_payment_attempts WHERE id=? FOR UPDATE',[$attempt])->fetch();if(($d['confirm_actual_bank']??false)!==true)crm_fail(422,'Зафиксируйте только фактически выполненный возврат по реальным данным банка.');$amount=bill_minor($d['amount']??null);$refunds=crm_query("SELECT amount_minor FROM nd_refunds WHERE attempt_id=? AND state='succeeded' FOR UPDATE",[$attempt])->fetchAll();$used=array_sum(array_column($refunds,'amount_minor'));if($amount<1||$used+$amount>(int)$p['amount_minor'])crm_fail(422,'Возврат не может превышать оставшуюся сумму данного поступления.');$date=lc_paid_at($d);$reference=cc_text($d,'reference',190);$reason=cc_text($d,'reason',500);$entry=cc_text($d,'bank_entry_id',190);$binding=lc_binding($a,(int)$i['schedule']['binding_id']);$input=json_decode($binding['input_snapshot'],true);$hash=hash('sha256',$input['fields']['bank_account']."\0".$entry);if(crm_query('SELECT id FROM nd_lc_bank_records WHERE bank_entry_hash=?',[$hash])->fetchColumn())crm_fail(409,'Банковская операция уже зафиксирована.');
 crm_query("INSERT INTO nd_refunds(attempt_id,request_key,provider_id,amount_minor,reason,state,verified_at) VALUES (?,?,?,?,?,'succeeded',UTC_TIMESTAMP())",[$attempt,$d['request_key'],'manual-refund:'.$hash,$amount,$reason]);$refund=(int)db()->lastInsertId();crm_query("INSERT INTO nd_lc_bank_records(refund_id,bank_entry_hash,bank_reference,payer,paid_at,method,reason,verified_by) VALUES (?,?,?,?,?,'bank_other',?,1)",[$refund,$hash,$reference,'Возврат по поступлению №'.$attempt,$date,$reason]);
 $task=crm_query('SELECT r.id FROM nd_lc_receipt_tasks r JOIN nd_payment_transactions t ON t.id=r.transaction_id WHERE t.attempt_id=? FOR UPDATE',[$attempt])->fetchColumn();if(!$task)crm_fail(409,'Для исходного поступления не найдена задача чека.');crm_query("UPDATE nd_lc_receipt_tasks SET state='CORRECTION_NEEDED',version=version+1 WHERE id=?",[$task]);crm_query("INSERT INTO nd_lc_receipt_evidence(task_id,action,refund_id,reason,recorded_by) VALUES (?,'REFUND_REVIEW_REQUIRED',?,?,1)",[$task,$refund,$reason]);lc_audit($a,'refund',$refund,'actual_refund_owner_recorded',null,['amount_minor'=>$amount,'attempt_id'=>$attempt,'reason'=>$reason]);bill_emit('lc-refund:'.$refund,'refund_completed','invoices',(int)$i['id'],(int)$i['customer_id']);return ['ok'=>true,'id'=>$refund,'mytax_correction_required'=>true,'refund_initiated_by_application'=>false];
}

function lc_claim_decide(array $a,int $id,string $action,array $d):array{
 cc_owner($a);$claim=crm_query('SELECT * FROM nd_lc_payment_claims WHERE id=?',[$id])->fetch();if(!$claim)crm_fail(404,'Сообщение не найдено.');$i=lc_invoice($a,(int)$claim['invoice_id'],true);$claim=crm_query('SELECT * FROM nd_lc_payment_claims WHERE id=? FOR UPDATE',[$id])->fetch();crm_version($d,$claim);if($claim['state']!=='REPORTED'||($d['confirm']??false)!==true)crm_fail(409,'Сообщение уже рассмотрено или решение не подтверждено.');$reason=cc_text($d,'reason',2000);$attempt=null;
 if($action==='link'){$attempt=cc_id($d['attempt_id']??null);$p=crm_query("SELECT p.id FROM nd_payment_attempts p JOIN nd_payment_transactions t ON t.attempt_id=p.id WHERE p.id=? AND p.invoice_id=? AND p.provider='manual_bank'",[$attempt,$i['id']])->fetch();if(!$p)crm_fail(422,'Выберите уже подтверждённое поступление этого запроса оплаты.');$state='RECONCILED';}elseif($action==='reject')$state='REJECTED';else crm_fail(404,'Действие не найдено.');
 crm_query('UPDATE nd_lc_payment_claims SET state=?,matched_attempt_id=?,reason=?,version=version+1 WHERE id=?',[$state,$attempt,$reason,$id]);lc_audit($a,'claim',$id,$state,(int)$claim['version'],['attempt_id'=>$attempt,'reason'=>$reason,'new_income_created'=>false]);return ['ok'=>true,'id'=>$id];
}
function lc_prior_allocated_net(array $invoice):int{
 if(crm_query("SELECT state FROM nd_schema_migrations WHERE version='017_lifecycle_closure'")->fetchColumn()!=='applied')return 0;$net=0;foreach(crm_query('SELECT a.invoice_snapshot FROM nd_lc_change_applications a JOIN nd_lc_scope_changes c ON c.id=a.change_id WHERE c.order_id=?',[$invoice['order_id']])->fetchAll() as $application)foreach(json_decode($application['invoice_snapshot'],true) as $old)if((int)$old['invoice_id']===(int)$invoice['id'])$net=max($net,(int)$old['balance']['net_minor']);return $net;
}
function lc_finance_read(array $a):array{
 $args=[];$where='';if($a['type']==='customer'){$where=' WHERE i.customer_id=?';$args[]=$a['customer_id'];}$items=crm_query('SELECT i.* FROM nd_invoices i JOIN nd_lc_schedule_entries s ON s.invoice_id=i.id'.$where.' ORDER BY i.id DESC LIMIT 100',$args)->fetchAll();
 foreach($items as &$i){$i['balance']=bill_balance($i);$i['prior_income_allocated_minor']=lc_prior_allocated_net($i);$i['overpayment_minor']=max(0,$i['balance']['net_minor']-max((int)$i['total_minor']-$i['balance']['credited_minor'],$i['prior_income_allocated_minor']));$i['snapshot']=json_decode($i['snapshot'],true);$i['claims']=crm_query('SELECT id,account_id,amount_minor,paid_at,payer,reference,state,matched_attempt_id,reason,version FROM nd_lc_payment_claims WHERE invoice_id=? ORDER BY id DESC',[$i['id']])->fetchAll();$i['payments']=crm_query("SELECT p.id,p.amount_minor,p.verified_at,t.settled_at,'OWNER_ATTESTED' AS evidence_source FROM nd_payment_attempts p JOIN nd_payment_transactions t ON t.attempt_id=p.id WHERE p.invoice_id=? AND p.provider='manual_bank' ORDER BY p.id",[$i['id']])->fetchAll();}unset($i);
 $args=[];$where='';if($a['type']==='customer'){$where=' WHERE o.customer_id=?';$args[]=$a['customer_id'];}$receipts=crm_query('SELECT r.* FROM nd_lc_receipt_tasks r JOIN nd_orders o ON o.id=r.order_id'.$where.' ORDER BY r.id DESC LIMIT 100',$args)->fetchAll();foreach($receipts as &$r){$r['overdue']=in_array($r['state'],['MISSING','OWNER_RECORDED'],true)&&$r['due_at']<gmdate('Y-m-d H:i:s');$r['independently_verified']=false;$r['evidence']=crm_query('SELECT action,official_url,file_id,external_reference,issued_at,transmitted_at,transmission_channel,refund_id,reason,evidence_source,created_at FROM nd_lc_receipt_evidence WHERE task_id=? ORDER BY id',[$r['id']])->fetchAll();}unset($r);return ['ok'=>true,'items'=>$items,'receipts'=>$receipts,'acquiring_enabled'=>false,'banking_integration_enabled'=>false,'mytax_integration_enabled'=>false];
}
